// BX News content schema (docs/03-technical-architecture.md section 5).
// Auth tables (user, session, account, verification) live in auth-schema.ts
// and are generated by the Better Auth CLI.
import {
  pgTable,
  pgEnum,
  uuid,
  text,
  boolean,
  integer,
  jsonb,
  timestamp,
  uniqueIndex,
  index,
  primaryKey,
  type AnyPgColumn,
} from "drizzle-orm/pg-core";
import { user } from "./auth-schema";

export * from "./auth-schema";

export const articleStatus = pgEnum("article_status", [
  "draft",
  "in_review",
  "changes_requested",
  "approved",
  "scheduled",
  "published",
  "unpublished",
  "spiked",
]);

export const articleType = pgEnum("article_type", [
  "news",
  "analysis",
  "opinion",
  "feature",
  "bulletin",
  "photo_story",
  "sponsored",
]);

export const articlePriority = pgEnum("article_priority", [
  "normal",
  "important",
  "breaking",
]);

const timestamps = {
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
};

/** Public author page + internal staff details, one per login. */
export const staffProfile = pgTable("staff_profile", {
  userId: text("user_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  displayName: text("display_name").notNull(),
  slug: text("slug").notNull().unique(),
  jobTitle: text("job_title"),
  bio: text("bio"),
  xHandle: text("x_handle"),
  // Portrait for the author page; any photo from the library.
  photoMediaId: uuid("photo_media_id").references((): AnyPgColumn => media.id, { onDelete: "set null" }),
  isPublic: boolean("is_public").notNull().default(false),
  ...timestamps,
});

export const section = pgTable("section", {
  id: uuid("id").primaryKey().defaultRandom(),
  parentId: uuid("parent_id").references((): AnyPgColumn => section.id),
  slug: text("slug").notNull().unique(),
  name: text("name").notNull(),
  description: text("description"),
  sortOrder: integer("sort_order").notNull().default(0),
  isActive: boolean("is_active").notNull().default(true),
  showInNav: boolean("show_in_nav").notNull().default(true),
  ...timestamps,
});

export const tag = pgTable("tag", {
  id: uuid("id").primaryKey().defaultRandom(),
  slug: text("slug").notNull().unique(),
  name: text("name").notNull(),
  ...timestamps,
});

export const media = pgTable("media", {
  id: uuid("id").primaryKey().defaultRandom(),
  r2Key: text("r2_key").notNull(),
  variants: jsonb("variants").notNull(), // { "480": key, "960": key, "1600": key }
  width: integer("width"),
  height: integer("height"),
  mime: text("mime"),
  bytes: integer("bytes"),
  caption: text("caption"),
  altText: text("alt_text").notNull(),
  credit: text("credit").notNull(),
  licence: text("licence"),
  uploadedBy: text("uploaded_by")
    .notNull()
    .references(() => user.id),
  ...timestamps,
});

/** Language-independent core of a story. */
export const article = pgTable(
  "article",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    type: articleType("type").notNull().default("news"),
    status: articleStatus("status").notNull().default("draft"),
    priority: articlePriority("priority").notNull().default("normal"),
    primarySectionId: uuid("primary_section_id")
      .notNull()
      .references(() => section.id),
    leadMediaId: uuid("lead_media_id").references(() => media.id),
    youtubeVideoId: text("youtube_video_id"),
    legalHold: boolean("legal_hold").notNull().default(false),
    createdBy: text("created_by")
      .notNull()
      .references(() => user.id),
    scheduledAt: timestamp("scheduled_at", { withTimezone: true }),
    firstPublishedAt: timestamp("first_published_at", { withTimezone: true }),
    publishedAt: timestamp("published_at", { withTimezone: true }),
    updatedPublicAt: timestamp("updated_public_at", { withTimezone: true }),
    ...timestamps,
  },
  (t) => [
    index("article_status_published_idx").on(t.status, t.publishedAt),
    index("article_section_idx").on(t.primarySectionId),
  ],
);

/** Language versions. English only at launch (D-004). */
export const articleTranslation = pgTable(
  "article_translation",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    articleId: uuid("article_id")
      .notNull()
      .references(() => article.id, { onDelete: "cascade" }),
    lang: text("lang").notNull().default("en"), // en | lg | sw
    headline: text("headline").notNull(),
    standfirst: text("standfirst"),
    body: jsonb("body").notNull().default({}), // Tiptap JSON
    slug: text("slug").notNull(),
    seoTitle: text("seo_title"),
    seoDescription: text("seo_description"),
    socialHeadline: text("social_headline"),
    ...timestamps,
  },
  (t) => [
    uniqueIndex("translation_lang_slug_idx").on(t.lang, t.slug),
    uniqueIndex("translation_article_lang_idx").on(t.articleId, t.lang),
  ],
);

export const articleAuthor = pgTable(
  "article_author",
  {
    articleId: uuid("article_id")
      .notNull()
      .references(() => article.id, { onDelete: "cascade" }),
    staffId: text("staff_id")
      .notNull()
      .references(() => staffProfile.userId),
    position: integer("position").notNull().default(0),
  },
  (t) => [primaryKey({ columns: [t.articleId, t.staffId] })],
);

export const articleTag = pgTable(
  "article_tag",
  {
    articleId: uuid("article_id")
      .notNull()
      .references(() => article.id, { onDelete: "cascade" }),
    tagId: uuid("tag_id")
      .notNull()
      .references(() => tag.id, { onDelete: "cascade" }),
  },
  (t) => [primaryKey({ columns: [t.articleId, t.tagId] })],
);

/**
 * Notes between writers and editors on a story: why it was sent back, spiked
 * or unpublished, plus general comments. Never shown to readers.
 */
export const editorialNote = pgTable(
  "editorial_note",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    articleId: uuid("article_id")
      .notNull()
      .references(() => article.id, { onDelete: "cascade" }),
    authorId: text("author_id")
      .notNull()
      .references(() => user.id),
    kind: text("kind").notNull().default("note"), // note | request_changes | spike | unpublish
    body: text("body").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("editorial_note_article_idx").on(t.articleId, t.createdAt)],
);

/**
 * A copy of the story's words each time readers could see a new version
 * (publish, edit while live, correction): proof of what was said and when.
 */
export const articleRevision = pgTable(
  "article_revision",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    articleId: uuid("article_id")
      .notNull()
      .references(() => article.id, { onDelete: "cascade" }),
    lang: text("lang").notNull().default("en"),
    headline: text("headline").notNull(),
    standfirst: text("standfirst"),
    body: jsonb("body").notNull(),
    leadMediaId: uuid("lead_media_id"),
    reason: text("reason").notNull(), // publish | update | correction
    createdBy: text("created_by").references(() => user.id),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("article_revision_article_idx").on(t.articleId, t.createdAt)],
);

/** Public, dated corrections shown under the story and on /corrections. */
export const articleCorrection = pgTable(
  "article_correction",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    articleId: uuid("article_id")
      .notNull()
      .references(() => article.id, { onDelete: "cascade" }),
    body: text("body").notNull(),
    createdBy: text("created_by")
      .notNull()
      .references(() => user.id),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("article_correction_created_idx").on(t.createdAt)],
);

/**
 * Editor-chosen homepage places (Blueprint 8.1): zone "lead" (position 0) and
 * "top" (positions 1-4). Empty or expired places fall back automatically.
 */
export const homepageSlot = pgTable(
  "homepage_slot",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    zone: text("zone").notNull(), // lead | top
    position: integer("position").notNull(),
    articleId: uuid("article_id")
      .notNull()
      .references(() => article.id, { onDelete: "cascade" }),
    overrideHeadline: text("override_headline"),
    pinnedUntil: timestamp("pinned_until", { withTimezone: true }),
    updatedBy: text("updated_by").references(() => user.id),
    ...timestamps,
  },
  (t) => [uniqueIndex("homepage_slot_zone_position_idx").on(t.zone, t.position)],
);

/** Site-wide breaking banner. One at a time; it ends at expires_at or when cleared. */
export const breakingAlert = pgTable(
  "breaking_alert",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    text: text("text").notNull(),
    articleId: uuid("article_id").references(() => article.id, { onDelete: "set null" }),
    startsAt: timestamp("starts_at", { withTimezone: true }).notNull().defaultNow(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    clearedAt: timestamp("cleared_at", { withTimezone: true }),
    createdBy: text("created_by")
      .notNull()
      .references(() => user.id),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("breaking_alert_expires_idx").on(t.expiresAt)],
);

/** Append-only security trail. */
export const auditLog = pgTable(
  "audit_log",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    actorId: text("actor_id"),
    action: text("action").notNull(), // e.g. "article.publish"
    entity: text("entity").notNull(),
    entityId: text("entity_id"),
    details: jsonb("details"),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  },
  (t) => [index("audit_created_idx").on(t.createdAt)],
);
